class Solution {
    std::string s;
    int memo[20][45][2][2];

    int dp(int idx, int bal, bool is_less, bool is_started) {
        if (idx == (int)s.size()) {
            return (is_started && bal == 20) ? 1 : 0;
        }
        if (memo[idx][bal][is_less][is_started] != -1) {
            return memo[idx][bal][is_less][is_started];
        }

        int limit = is_less ? 9 : (s[idx] - '0');
        int total = 0;

        for (int dig = 0; dig <= limit; ++dig) {
