import java.util.*;

class Solution {
    private String s;
    private int[][][][] memo;

    public int countEvenlyGoodIntegers(long n) {
        s = String.valueOf(n);
        memo = new int[s.length() + 1][45][2][2];
        for (int[][][] d1 : memo) {
            for (int[][] d2 : d1) {
                for (int[] d3 : d2) Arrays.fill(d3, -1);
            }
        }
        return dp(0, 20, 0, 0);
    }

    private int dp(int idx, int bal, int isLess, int isStarted) {
        if (idx == s.length()) {
            return (isStarted == 1 && bal == 20) ? 1 : 0;
        }
        if (memo[idx][bal][isLess][isStarted] != -1) {
            return memo[idx][bal][isLess][isStarted];
        }

        int limit = (isLess == 1) ? 9 : (s.charAt(idx) - '0');
        int total = 0;

        for (int dig = 0; dig <= limit; dig++) {
            int nextLess = (isLess == 1 || dig < limit) ? 1 : 0;
            if (isStarted == 0 && dig == 0) {
                total += dp(idx + 1, bal, nextLess, 0);
            } else {
                int nextBal = bal + (dig % 2 == 0 ? 1 : -1);
                total += dp(idx + 1, nextBal, nextLess, 1);
            }
        }
        return memo[idx][bal][isLess][isStarted] = total;
    }
}

function countEvenlyGoodIntegers(n) {
    const s = String(n);
    const len = s.length;
    const memo = new Map();

    function dp(idx, bal, isLess, isStarted) {
        if (idx === len) {
            return isStarted && bal === 0 ? 1 : 0;
        }
        const key = `${idx},${bal},${isLess ? 1 : 0},${isStarted ? 1 : 0}`;
        if (memo.has(key)) return memo.get(key);

        const limit = isLess ? 9 : parseInt(s[idx], 10);
        let total = 0;

        for (let dig = 0; dig <= limit; dig++) {
            const nextLess = isLess || dig < limit;
            if (!isStarted && dig === 0) {
                total += dp(idx + 1, bal, nextLess, false);
            } else {
                const nextBal = bal + (dig % 2 === 0 ? 1 : -1);
                total += dp(idx + 1, nextBal, nextLess, true);
            }
        }
        memo.set(key, total);
        return total;
    }

    return dp(0, 0, false, false);
